{"hypotheses": [
  {
    "name": "Profitability-Quality Spread in Low Volatility Regimes",
    "mechanism": "Combining operating profitability (OperProf) and accruals-based quality (AccrualsBM), minus junk momentum (Mom6mJunk), should capture robust, high-quality growth stocks while hedging out low-quality, high-momentum 'junk' exposures. Conditioning on VIX_BELOW_TRAILING_MEDIAN amplifies this since defensive, quality stocks outperform when market volatility is subdued.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 1.0, "primitive": "AccrualsBM"},
        {"weight": -1.0, "primitive": "Mom6mJunk"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "Mom6mJunk", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "large", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 1.0,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Overlooked Value under Negative Term Spread",
    "mechanism": "Combining classic book-to-market (BM) with analyst forecast pessimism (AOP) and net payout yield (NetPayoutYield) isolates undervalued stocks ignored by consensus. This blend should outperform specifically when TERM_SPREAD_NEGATIVE signals economic stress and investor risk-aversion, as such environments increase mispricing due to neglect.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": 0.5, "primitive": "AOP"},
        {"weight": 0.5, "primitive": "NetPayoutYield"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "AOP", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Cash Efficiency and Customer Momentum Blend",
    "mechanism": "Firms efficient in converting cash (CashProd) and showing signs of customer momentum (CustomerMomentum), minus high equity issuance (CompEquIss), should deliver premium returns by capturing sustainable business quality and external validation, while avoiding dilution-prone firms likely overvalued.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CashProd"},
        {"weight": 1.0, "primitive": "CustomerMomentum"},
        {"weight": -1.0, "primitive": "CompEquIss"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "CompEquIss", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": null
  },
  {
    "name": "Volatility-Resilient Growth minus Financial Leverage",
    "mechanism": "Firms with high intermediate momentum (IntMom) and high R&D to market cap (RD), but low book leverage (BookLeverage), are likely to outperform especially when market volatility is above-trend (VIX_ABOVE_TRAILING_MEDIAN). This blend captures innovative, resilient growth with risk control.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IntMom"},
        {"weight": 1.0, "primitive": "RD"},
        {"weight": -1.0, "primitive": "BookLeverage"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "BookLeverage", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Analyst Optimism Reversal during Down Markets",
    "mechanism": "Shorting analyst optimism (AOP) and long short-term reversal (STreversal) and Piotroski F-score (PS) captures the post-euphoria underperformance of analyst favorites, balanced with return stabilization and quality tilt, enhanced when MKT_TRAILING_12M_DOWN signals recent market drawdowns.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AOP"},
        {"weight": 1.0, "primitive": "STreversal"},
        {"weight": 0.5, "primitive": "PS"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Shareholder Yield and Idiosyncratic Volatility Mitigation",
    "mechanism": "Combining net payout yield (NetPayoutYield) and earnings forecast revision (AnalystRevision), minus idiosyncratic volatility (IdioVol3F), targets high-shareholder-return firms receiving positive analyst attention while screening out excessive risk-takers. This should provide more stable outperformance than any component alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "NetPayoutYield"},
        {"weight": 0.5, "primitive": "AnalystRevision"},
        {"weight": -1.0, "primitive": "IdioVol3F"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "correlation", "primitive": "IdioVol3F", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 42
  },
  {
    "name": "Return Skewness and Off-Season Momentum",
    "mechanism": "Stocks with high positive return skew (ReturnSkew) and off-season momentum (MomOffSeason), minus firms with high realized volatility (RealizedVol), capture stocks with attractive tail risk while filtering excessive risk. The effect should be most pronounced when the market has trended up over the past year (MKT_TRAILING_12M_UP).",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ReturnSkew"},
        {"weight": 1.0, "primitive": "MomOffSeason"},
        {"weight": -1.0, "primitive": "RealizedVol"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "RealizedVol", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Intangible-Adjusted Quality Defensive",
    "mechanism": "Combining Piotroski F-score (PS), intangible-adjusted earnings yield (IntanEP), and subtracting external financing (XFIN) isolates stocks with strong fundamentals and low reliance on external capital. This composite should deliver defensive returns, especially in small caps, by emphasizing fundamental resilience and capital discipline.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "PS"},
        {"weight": 1.0, "primitive": "IntanEP"},
        {"weight": -0.5, "primitive": "XFIN"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.95,
    "expected_decay_half_life_months": 34
  }
]}
